#include "tgcloud/telegram/bot_client.hpp"
#include <curl/curl.h>
namespace tgcloud::telegram { static size_t write_cb(char*p,size_t s,size_t n,void*u){static_cast<std::string*>(u)->append(p,s*n);return s*n;} ApiResponse call(const std::string&u){CURL*c=curl_easy_init();ApiResponse r;if(!c)return r;curl_easy_setopt(c,CURLOPT_URL,u.c_str());curl_easy_setopt(c,CURLOPT_WRITEFUNCTION,write_cb);curl_easy_setopt(c,CURLOPT_WRITEDATA,&r.body);curl_easy_setopt(c,CURLOPT_TIMEOUT,30L);auto code=curl_easy_perform(c);if(code==CURLE_OK)curl_easy_getinfo(c,CURLINFO_RESPONSE_CODE,&r.http_status);curl_easy_cleanup(c);return r;} ApiResponse BotClient::get_me()const{return call(base_+"/bot"+token_+"/getMe");} ApiResponse BotClient::get_chat(std::string id)const{return call(base_+"/bot"+token_+"/getChat?chat_id="+id);} ApiResponse BotClient::get_file(std::string id)const{return call(base_+"/bot"+token_+"/getFile?file_id="+id); } ApiResponse BotClient::download_to(std::string url,std::string dest)const{CURL*c=curl_easy_init();ApiResponse r;if(!c)return r;FILE*f=fopen(dest.c_str(),"wb");if(!f){curl_easy_cleanup(c);return r;}curl_easy_setopt(c,CURLOPT_URL,url.c_str());curl_easy_setopt(c,CURLOPT_WRITEDATA,f);curl_easy_setopt(c,CURLOPT_TIMEOUT,300L);auto code=curl_easy_perform(c);if(code==CURLE_OK)curl_easy_getinfo(c,CURLINFO_RESPONSE_CODE,&r.http_status);fclose(f);curl_easy_cleanup(c);return r;} ApiResponse BotClient::send_document(std::string chat,std::string file,std::string caption)const{CURL*c=curl_easy_init();ApiResponse r;if(!c)return r;auto url=base_+"/bot"+token_+"/sendDocument";curl_mime*m=curl_mime_init(c);auto*p=curl_mime_addpart(m);curl_mime_name(p,"chat_id");curl_mime_data(p,chat.c_str(),CURL_ZERO_TERMINATED);p=curl_mime_addpart(m);curl_mime_name(p,"document");curl_mime_filedata(p,file.c_str());if(!caption.empty()){p=curl_mime_addpart(m);curl_mime_name(p,"caption");curl_mime_data(p,caption.c_str(),CURL_ZERO_TERMINATED);}curl_easy_setopt(c,CURLOPT_URL,url.c_str());curl_easy_setopt(c,CURLOPT_MIMEPOST,m);curl_easy_setopt(c,CURLOPT_WRITEFUNCTION,write_cb);curl_easy_setopt(c,CURLOPT_WRITEDATA,&r.body);curl_easy_setopt(c,CURLOPT_TIMEOUT,300L);if(curl_easy_perform(c)==CURLE_OK)curl_easy_getinfo(c,CURLINFO_RESPONSE_CODE,&r.http_status);curl_mime_free(m);curl_easy_cleanup(c);return r;} }
